import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    # We can keep the array elements as strings to avoid the overhead of int conversion,
    # since we only need to perform exact equality checks.
    A = input_data[2 : N + 2]
    B = input_data[N + 2 : N + M + 2]

    # Find the leftmost match of B in A
    L = []
    j = 0
    for i in range(N):
        if A[i] == B[j]:
            L.append(i)
            j += 1
            if j == M:
                break

    # If B is not even a subsequence of A once, output No
    if j < M:
        print("No")
        return

    # Find the rightmost match of B in A
    R = []
    j = M - 1
    for i in range(N - 1, -1, -1):
        if A[i] == B[j]:
            R.append(i)
            j -= 1
            if j < 0:
                break
    R.reverse()

    # If the leftmost match indices and the rightmost match indices differ,
    # there must be at least two subsequences matching B.
    if L != R:
        print("Yes")
    else:
        print("No")

if __name__ == '__main__':
    solve()
